const text = String(params.json || params.input || params.text || '').trim();
if (!text) return { error: 'pass params.json (the JSON string to format)' };
try {
  const parsed = JSON.parse(text);
  return { pretty: JSON.stringify(parsed, null, 2), bytes_in: text.length };
} catch (e) {
  // Try to give a useful pointer
  const m = String(e.message).match(/position (\d+)/);
  const at = m ? Number(m[1]) : -1;
  const window = at >= 0 ? text.slice(Math.max(0, at - 20), at + 20) : '';
  return { error: e.message, hint: window ? `near: …${window}…` : 'unparseable JSON' };
}
